{"implementation":"def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    children = {}
    node_by_id = {}
    for node in nodes:
        node_id = node['id']
        parent = node.get('parent')
        if parent is not None:
            children.setdefault(parent, []).append(node_id)
        node_by_id[node_id] = node
    root_id = None
    for node in nodes:
        if node['parent'] is None:
            root_id = node['id']
            break
    retained = []
    visit_order = []
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        node = node_by_id[node_id]
        visit_order.append(node_id)
        removable = node['removable']
        utility = node['utility']
        if removable and utility < threshold:
            continue
        retained.append(node_id)
        child_ids = children.get(node_id, [])
        for child_id in reversed(child_ids):
            stack.append(child_id)
    return {
        "retained_node_ids": retained,
        "visit_order": visit_order
    }"}
